import struct,zlib
from pathlib import Path
from collections import deque

def png_read(p,decode=False):
 b=Path(p).read_bytes();w,h,depth,ct,comp,filt,inter=struct.unpack('>IIBBBBB',b[16:29])
 print(p.rsplit('/',1)[-1], 'dimensions',w,h,'bit_depth',depth,'color_type',ct,'interlace',inter)
 if not decode:return w,h,None,None
 channels={2:3,6:4}[ct]; assert depth==8 and inter==0
 chunks=[];pos=8
 while pos<len(b):
  n=struct.unpack('>I',b[pos:pos+4])[0];typ=b[pos+4:pos+8]
  if typ==b'IDAT':chunks.append(b[pos+8:pos+8+n])
  pos+=n+12
 raw=zlib.decompress(b''.join(chunks));stride=w*channels;prev=bytearray(stride);rows=[];pos=0
 for y in range(h):
  f=raw[pos];row=bytearray(raw[pos+1:pos+1+stride]);pos+=stride+1
  for i in range(stride):
   a=row[i-channels] if i>=channels else 0;bb=prev[i];c=prev[i-channels] if i>=channels else 0
   if f==1:row[i]=(row[i]+a)&255
   elif f==2:row[i]=(row[i]+bb)&255
   elif f==3:row[i]=(row[i]+((a+bb)//2))&255
   elif f==4:
    q=a+bb-c;pa=abs(q-a);pb=abs(q-bb);pc=abs(q-c);v=a if pa<=pb and pa<=pc else bb if pb<=pc else c
    row[i]=(row[i]+v)&255
   elif f"'!=0:raise ValueError(f)
  rows.append(row);prev=row
 return w,h,channels,rows
